-- Pharmville standalone effective schema: reconstructed through V0030.
-- PostgreSQL 18 fresh-install verified; no migration runner, ORM or seed data.
-- Install only on a new empty database using a trusted DDL owner.
-- Prerequisites and external runtime-login mapping: 04-Database/Installation.md.
-- A sufficiently privileged installer must create pgcrypto and NOLOGIN groups.
-- No existing database or pre-existing unsafe role is modified by this file.
BEGIN;
SET LOCAL lock_timeout = '5s';
DO $capability_roles$
DECLARE role_name text; existing record;
BEGIN
  FOREACH role_name IN ARRAY ARRAY['pharmville_customer_api','pharmville_staff_api','pharmville_reporting_worker','pharmville_integration_worker'] LOOP
    SELECT * INTO existing FROM pg_roles WHERE rolname=role_name;
    IF FOUND THEN
      IF existing.rolsuper OR existing.rolbypassrls OR existing.rolcanlogin OR existing.rolinherit
         OR existing.rolcreatedb OR existing.rolcreaterole OR existing.rolreplication THEN
        RAISE EXCEPTION 'Unsafe pre-existing capability group: %',role_name;
      END IF;
    ELSE
      EXECUTE format('CREATE ROLE %I NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT NOCREATEDB NOCREATEROLE NOREPLICATION',role_name);
    END IF;
  END LOOP;
END
$capability_roles$;
