CREATE TABLE appointment.appointment_slots (
    practitioner_service_id uuid NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    capacity integer DEFAULT 1 NOT NULL,
    booked_count integer DEFAULT 0 NOT NULL,
    status character varying(32) DEFAULT 'open'::character varying NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    internal_id bigint NOT NULL,
    practitioner_service_id_internal_id bigint NOT NULL,
    CONSTRAINT ck_appointment_appointment_slots_booking_capacity CHECK (((booked_count >= 0) AND (booked_count <= capacity))),
    CONSTRAINT ck_appointment_appointment_slots_capacity_positive CHECK ((capacity > 0)),
    CONSTRAINT ck_appointment_appointment_slots_numeric_pair_practitio_0abf CHECK (((practitioner_service_id IS NULL) = (practitioner_service_id_internal_id IS NULL))),
    CONSTRAINT ck_appointment_appointment_slots_row_version_positive CHECK ((row_version > 0)),
    CONSTRAINT ck_appointment_appointment_slots_valid_window CHECK ((ends_at > starts_at))
);


