-- Name: order_items customer_own_item; Type: POLICY; Schema: commerce; Owner: -
--

CREATE POLICY customer_own_item ON commerce.order_items FOR SELECT TO pharmville_customer_api USING ((EXISTS ( SELECT 1
   FROM commerce.orders o
  WHERE ((o.id = order_items.order_id) AND (o.user_id = platform.authenticated_customer())))));


--
-- Name: orders customer_own_order; Type: POLICY; Schema: commerce; Owner: -
--

CREATE POLICY customer_own_order ON commerce.orders FOR SELECT TO pharmville_customer_api USING ((user_id = platform.authenticated_customer()));


